extern "C" unsigned char* MD5(const unsigned char*,size_t,unsigned char*);
extern "C" const char* OpenSSL_version(int);
void oracle(const unsigned int words[2],int len,unsigned int*out){unsigned char md[16];if(!MD5((const unsigned char*)words,len,md))abort();memcpy(out,md,16);}
struct Fixture{int len,base,n,target,index;unsigned int sd[4],found[4];unsigned char key[8],expected_key[8];Fixture(int id){len=id==0?7:id==2?6:5;base=id==0?4:id==1?7:id==2?5:8;n=FindKeyspaceSize(len,base);target=id==0?0:id==1?n-1:id==2?n/3+7:-1;memset(sd,0,16);memset(expected_key,0,8);if(target>=0){IndexToKey(target,len,base,expected_key);unsigned int words[2];memcpy(words,expected_key,8);oracle(words,len,sd);}int cpuindex=-1;unsigned char cpukey[8]={0};unsigned int cpudigest[4]={0};FindKeyWithDigest_CPU(sd,len,base,&cpuindex,cpukey,cpudigest);if(cpuindex!=target||memcmp(cpukey,expected_key,8)||memcmp(cpudigest,target<0?found_zero():sd,16))abort();}static const unsigned int* found_zero(){static const unsigned int z[4]={0};return z;}void call(){index=-1;memset(key,0,8);memset(found,0,16);FindKeyWithDigest_GPU(sd,len,base,&index,key,found);}};
__global__ void digest_probe(const unsigned int*w0,const unsigned int*w1,const int*lens,unsigned int*out,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n){unsigned int words[2]={w0[i],w1[i]},z[4];md5_2words(words,lens[i],z);for(int j=0;j<4;j++)out[4*i+j]=z[j];}}
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):5;std::vector<Fixture>fs;std::vector<unsigned int>w0,w1,gold;std::vector<int>lens;std::vector<long long>prefix;auto add=[&](const unsigned int*words,int len){unsigned int z[4],source[4];oracle(words,len,z);unsigned int tmp[2]={words[0],words[1]};md5_2words(tmp,len,source);if(memcmp(z,source,16))abort();w0.push_back(words[0]);w1.push_back(words[1]);lens.push_back(len);gold.insert(gold.end(),z,z+4);};for(int id=0;id<4;id++){fs.emplace_back(id);auto&f=fs.back();prefix.insert(prefix.end(),{f.len,f.base,f.n});prefix.insert(prefix.end(),f.sd,f.sd+4);prefix.push_back(-1);for(int j=0;j<12;j++)prefix.push_back(0);int matches=0;for(int i=0;i<f.n;i++){unsigned char key[8]={0};IndexToKey(i,f.len,f.base,key);unsigned int words[2],z[4];memcpy(words,key,8);oracle(words,f.len,z);matches+=memcmp(z,f.sd,16)==0;add(words,f.len);}if(matches!=(f.target<0?0:1))abort();}for(int len=0;len<8;len++){unsigned char bytes[8]={0};for(int i=0;i<len;i++)bytes[i]=97+i;unsigned int words[2];memcpy(words,bytes,8);add(words,len);}for(int len=1;len<8;len++){unsigned char bytes[8]={0};for(int i=0;i<len;i++)bytes[i]=0x80+(i+1)*7;unsigned int words[2];memcpy(words,bytes,8);add(words,len);}prefix.push_back(lens.size());prefix.insert(prefix.end(),w0.begin(),w0.end());prefix.insert(prefix.end(),w1.begin(),w1.end());prefix.insert(prefix.end(),lens.begin(),lens.end());Dl_info info;dladdr((void*)MD5,&info);printf("CPU_ORACLE_OPENSSL %s path=%s\n",OpenSSL_version(0),info.dli_fname);unsigned int *d0,*d1,*dop;int*dl;cudaMalloc(&d0,w0.size()*4);cudaMalloc(&d1,w1.size()*4);cudaMalloc(&dl,lens.size()*4);cudaMalloc(&dop,gold.size()*4);cudaMemcpy(d0,w0.data(),w0.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(d1,w1.data(),w1.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(dl,lens.data(),lens.size()*4,cudaMemcpyHostToDevice);for(auto&f:fs)f.call();digest_probe<<<(lens.size()+255)/256,256>>>(d0,d1,dl,dop,lens.size());cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();for(int z=0;z<rep;z++)for(auto&f:fs)f.call();cudaDeviceSynchronize();double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep;digest_probe<<<(lens.size()+255)/256,256>>>(d0,d1,dl,dop,lens.size());cudaDeviceSynchronize();std::vector<unsigned int>pg(gold.size());cudaMemcpy(pg.data(),dop,pg.size()*4,cudaMemcpyDeviceToHost);bool ok=pg==gold&&cudaGetLastError()==cudaSuccess;std::vector<long long>got;for(auto&f:fs){ok&=f.index==f.target&&memcmp(f.key,f.expected_key,8)==0&&memcmp(f.found,f.target<0?Fixture::found_zero():f.sd,16)==0;got.push_back(f.index);for(auto v:f.key)got.push_back(v);for(auto v:f.found)got.push_back(v);}got.insert(got.end(),pg.begin(),pg.end());auto art=prefix;art.insert(art.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(art.data(),8,art.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0.0,\"max_rel_error\":0.0,\"timing_region\":\"four_complete_MD5searches_hostinclusive_alloc_initcopy_kernel_copy_free_excludes_digestprobe\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",got.size(),rep,path.c_str(),art.size());if(!ok)return 2;}cudaFree(d0);cudaFree(d1);cudaFree(dl);cudaFree(dop);}
